#include "server/schema.h"

#include "server/http.h"
#include "zonos3-openapi.h"   // generated by CMake: zonos3_openapi_json[], zonos3_openapi_json_len

#include <nlohmann/json-schema.hpp>

#include <map>
#include <memory>
#include <mutex>

namespace zs::schema {

using nlohmann::json_schema::json_validator;

const json & spec() {
    static const json doc = json::parse(std::string((const char *) zonos3_openapi_json, zonos3_openapi_json_len));
    return doc;
}

namespace {

// Collects every violation as a FastAPI-style detail entry. loc = ["body", path tokens...]; array indices are integers.
class Collector : public nlohmann::json_schema::basic_error_handler {
public:
    json detail = json::array();
    void error(const json::json_pointer & ptr, const json &, const std::string & message) override {
        basic_error_handler::error(ptr, json(), message);
        json loc = json::array({"body"});
        const std::string path = ptr.to_string();
        size_t pos = 0;
        while (pos < path.size()) {
            const size_t next = path.find('/', pos + 1);
            std::string token = path.substr(pos + 1, (next == std::string::npos ? path.size() : next) - pos - 1);
            for (size_t i; (i = token.find("~1")) != std::string::npos;) token.replace(i, 2, "/");
            for (size_t i; (i = token.find("~0")) != std::string::npos;) token.replace(i, 2, "~");
            const bool index = !token.empty() && token.find_first_not_of("0123456789") == std::string::npos &&
                               token.size() < 10;
            if (index) loc.push_back(std::stoi(token)); else loc.push_back(token);
            if (next == std::string::npos) break;
            pos = next;
        }
        // An unknown field names itself in the message ("... additional property 'x' ..."): point loc at it.
        static const std::string extra = "additional property '";
        const size_t at = message.find(extra);
        if (at != std::string::npos) {
            const size_t end = message.find('\'', at + extra.size());
            if (end != std::string::npos) loc.push_back(message.substr(at + extra.size(), end - at - extra.size()));
        }
        detail.push_back({{"loc", loc}, {"msg", message}, {"type", "value_error"}});
    }
};

std::mutex g_mtx;
std::map<std::string, std::shared_ptr<json_validator>> g_validators;

std::shared_ptr<json_validator> validator_for(const std::string & name) {
    std::lock_guard<std::mutex> lk(g_mtx);
    auto it = g_validators.find(name);
    if (it != g_validators.end()) return it->second;
    if (!spec()["components"]["schemas"].contains(name))
        throw std::runtime_error("api/openapi.json has no schema " + name);
    auto v = std::make_shared<json_validator>(
        [](const nlohmann::json_uri &, json & schema) { schema = spec(); },
        [](const std::string &, const std::string &) {});   // formats (binary, ...) are not request constraints
    v->set_root_schema(json{{"$ref", "openapi.json#/components/schemas/" + name}});
    g_validators[name] = v;
    return v;
}

}  // namespace

std::optional<json> validate(const std::string & name, const json & body) {
    auto v = validator_for(name);
    Collector errors;
    v->validate(body, errors);
    if (!errors) return std::nullopt;
    return json{{"detail", errors.detail}};
}

json parse_body(const httplib::Request & req, const std::string & name) {
    json body = json::parse(req.body, nullptr, /*allow_exceptions=*/false);
    if (body.is_discarded()) {
        size_t pos = 0;
        try { const json probe = json::parse(req.body); } catch (const json::parse_error & e) { pos = e.byte ? e.byte - 1 : 0; }
        throw HttpError(422, json{{"detail", json::array({json{{"loc", json::array({"body", pos})},
                                                               {"msg", "JSON decode error"},
                                                               {"type", "json_invalid"}}})}});
    }
    if (auto errors = validate(name, body)) throw HttpError(422, *errors);
    return body;
}

}  // namespace zs::schema
